import React, { useState } from 'react';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';
import MedicinesList from './components/MedicinesList';
import Cart from './components/Cart';
import Login from './components/Login';
import Profile from './components/Profile';
import './App.css';

function App() {
  const [cart, setCart] = useState([]);
  const [user, setUser] = useState(null);

  const addToCart = (medicine) => {
    setCart([...cart, medicine]);
  };

  const removeFromCart = (id) => {
    setCart(cart.filter(item => item.id !== id));
  };

  return (
    <Router>
      <div className="min-h-screen bg-gray-50">
        <nav className="bg-blue-600 text-white p-4 shadow-md flex justify-between items-center">
          <Link to="/" className="text-2xl font-bold">HealthPlus Pharmacy</Link>
          <div className="flex gap-4">
            <Link to="/" className="hover:underline">Home</Link>
            <Link to="/cart" className="hover:underline">Cart ({cart.length})</Link>
            {user ? (
              <Link to="/profile" className="hover:underline">Profile</Link>
            ) : (
              <Link to="/login" className="hover:underline">Login</Link>
            )}
          </div>
        </nav>

        <main className="p-8">
          <Routes>
            <Route path="/" element={<MedicinesList addToCart={addToCart} />} />
            <Route path="/cart" element={<Cart cart={cart} removeFromCart={removeFromCart} user={user} setCart={setCart} />} />
            <Route path="/login" element={<Login setUser={setUser} />} />
            <Route path="/profile" element={<Profile user={user} setUser={setUser} />} />
          </Routes>
        </main>
      </div>
    </Router>
  );
}

export default App;
